/* Flight-modal presentation pattern; scoped to the independent File builder. */
.cfbld-box{height:min(92vh,900px);max-width:1380px}.cfbld-header{background:linear-gradient(110deg,#ed5929,#b73716);padding:13px 18px}.cfbld-header>i{display:flex;align-items:center;justify-content:center;height:36px;width:36px;background:#ffffff25;border-radius:10px;font-size:18px}.cfbld-header button{border:0;padding:4px 10px;font-size:22px}.cfbld-steps{gap:0;align-items:stretch;padding:0 16px;background:#f7f9fc}.cfbld-steps [role=tab]{display:flex;align-items:center;gap:9px;border:0;border-bottom:2px solid transparent;border-radius:0;padding:11px 15px;background:transparent;color:#92a0b5;text-align:left;min-width:190px}.cfbld-steps [role=tab]>span:last-child{font-size:12px;font-weight:700}.cfbld-steps [role=tab] small{display:block;font-size:10px;font-weight:400;margin-top:2px}.cfbld-step-n{display:flex;align-items:center;justify-content:center;width:21px;height:21px;border-radius:50%;background:#e4e9f1;color:#71829a;font-size:10px;font-weight:700}.cfbld-steps [role=tab].is-on{color:#df4c22;border-bottom-color:#ed5929}.cfbld-steps .is-on .cfbld-step-n{background:#ed5929;color:#fff}.cfbld-steps [role=tab]:hover{background:#eef2f9}.cfbld-steps [role=tab]:focus-visible{outline:2px solid #596fe3;outline-offset:-3px}.cfbld-context{margin-left:auto;align-self:center;font-size:10px;color:#6f819b;text-align:right;padding-left:12px}.cfbld-body{padding:12px 14px}.cfbld-setup{display:grid;grid-template-columns:1.1fr 1fr;gap:14px}.cfbld-panel{border:1px solid #dfe6f3;border-radius:11px;padding:13px;background:#fff;align-self:start}.cfbld-panel h3{background:#f8faff;border-bottom:1px solid #e6edf7;padding:10px 13px;margin:-13px -13px 16px;font-size:10px;color:#617491;letter-spacing:.6px;border-radius:11px 11px 0 0;display:flex;align-items:center;gap:6px}.cfbld-panel h3 small{margin-left:auto;font-size:9px;font-weight:400;letter-spacing:0;color:#9ba9bf}.cfbld-panel p{line-height:1.7}.cfbld-box input,.cfbld-box select,.cfbld-box textarea{font-size:11px;border-radius:8px;padding:8px 9px}.cfbld-box label{font-size:10px}.cfbld-applicants-heading{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #edf1f7;padding:6px 0 11px;gap:10px}.cfbld-applicants-heading h3{margin:0;font-size:10px;letter-spacing:.8px;color:#657790}.cfbld-applicants-heading span{font-size:10px;color:#7b8faa}.cfbld-picker{display:flex;align-items:flex-end;gap:10px;background:#fff;border:1px solid #e1e8f4;margin-top:12px;padding:12px;border-radius:9px}.cfbld-holder-picker{flex:1;min-width:0}.cfbld-picker #cfbld-add{background:#f2f7ff;border:1px dashed #9bc3ff;color:#1673df;font-weight:700;white-space:nowrap;height:35px}.cfbld-box .cfbld-info{background:#f7faff;border:1px solid #e0e9f7;padding:7px 10px;border-radius:6px;font-size:10px;margin:10px 0}.cfbld-info i{color:#1673df;margin-right:5px}.cfbld-box #cfbld-empty{padding:45px 15px;text-align:center;border:1px dashed #dce5f3;border-radius:9px;color:#92a0b5;margin-top:16px;font-size:12px}.cfbld-card{margin:12px 0}.cfbld-card>header{padding:9px 12px}.cfbld-card>header strong{font-size:11px}.cfbld-card>header button{height:26px;padding:2px 7px;font-size:12px}.cfbld-columns{gap:12px;padding:10px}.cfbld-columns>section{padding:12px;background:#fff}.cfbld-columns>section>h3:first-child{padding:9px 12px;margin:-12px -12px 12px;border-bottom:1px solid #e5ecf6;background:#f8faff;color:#617491;font-size:10px;border-radius:9px 9px 0 0}.cfbld-box footer{padding:11px 16px}.cfbld-box footer span{font-size:10px;color:#586c8b}.cfbld-box #cfbld-next{background:#fff5f0;border-color:#ffd1bc;color:#df4c22}.cfbld-box .select2-container--default .select2-selection--multiple{min-height:36px;border:1px solid #d7dfed;border-radius:8px;padding:2px 6px;font-size:11px}.cfbld-box .select2-container--default .select2-selection--multiple .select2-selection__choice{border:1px solid #c5d9fb;background:#eff5ff;color:#355f99;margin-top:4px}.cfbld-box .select2-container--default .select2-selection--multiple .select2-search__f