/* Same geometry and notched fields as Flight's pb-sub / pb-svc / pb-sc-grid. */
.cfbld-card,.cfbld-card *{box-sizing:border-box}
.cfbld-columns{grid-template-columns:minmax(0,3fr) minmax(0,2fr);align-items:start;gap:10px;padding:10px}
.cfbld-left{display:flex;flex-direction:column;gap:10px;min-width:0}
.cfbld-left>section,.cfbld-columns>.cfbld-services{border:1px solid #e7ecf3;border-radius:10px;padding:10px;background:#fff;min-width:0}
.cfbld-left>section>h3:first-child,.cfbld-columns>.cfbld-services>h3:first-child{display:flex;align-items:center;gap:7px;padding:7px 11px;background:#fafbfd;border-bottom:1px solid #eef2f7;margin:-10px -10px 12px;border-radius:10px 10px 0 0;font-size:11px;font-weight:700;letter-spacing:.5px;text-transform:uppercase;color:#64748b}
.cfbld-columns h3 i{color:#94a3b8;font-size:11px}
.cfbld-services>h3 small{margin-left:auto;font-size:10px;color:#9ba9bf;font-weight:400;letter-spacing:0;text-transform:none}
.cfbld-card h4{font-size:11px;font-weight:600;color:#64748b;margin:10px 0}
.cfbld-card .cfbld-grid{gap:10px 8px}
.cfbld-card label:not(.cfbld-check):not(.cfbld-svc-tick){position:relative;display:flex;flex-direction:column;gap:0;min-width:0}
.cfbld-card .cfbld-lbl{position:relative;z-index:1;display:block;align-self:flex-start;width:fit-content;max-width:calc(100% - 16px);margin:0 0 -6px 8px;padding:0 4px;background:#fff;font-size:10.5px;line-height:12px;color:#475569;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cfbld-card input:not([type=checkbox]),.cfbld-card select,.cfbld-card textarea{border:1px solid #d1d5db;border-radius:8px;padding:9px 9px 7px;font-size:12px;color:#1a2035;background:#fff;min-width:0;height:35px;outline:none}
.cfbld-card textarea{height:50px;resize:vertical}
.cfbld-card input[type=file]{height:auto;font-size:11px;padding:8px}
.cfbld-card input:focus,.cfbld-card select:focus,.cfbld-card textarea:focus{border-color:#ea580c;box-shadow:0 0 0 3px #ea580c17}
.cfbld-card [data-bld-holder-info]{font-size:11px;line-height:1.6;margin-bottom:12px}
.cfbld-documents [data-bld-checklist],.cfbld-documents [data-bld-links]{display:flex;flex-wrap:wrap;gap:4px 14px;margin-bottom:12px;font-size:11px;color:#94a3b8}
.cfbld-card .cfbld-check{font-size:11px;margin:3px 0}
.cfbld-documents>small{display:block;color:#94a3b8;font-size:10px;line-height:1.5;margin-top:6px}
.cfbld-svc-list{display:grid;gap:6px;margin-top:12px}
.cfbld-svc{border:1px solid #e2e8f0;border-radius:9px;background:#fff;transition:border-color .12s,background .12s}
.cfbld-svc.is-selected{border-color:#6366f1;background:#eef2ff}
.cfbld-svc-head{display:flex;align-items:center;gap:10px;padding:5px 10px 5px 8px;min-height:40px}
.cfbld-box .cfbld-svc-tick{display:flex;flex-direction:row;align-items:center;gap:9px;flex:1;min-width:0;cursor:pointer;margin:0}
.cfbld-svc-tick input{flex-shrink:0;margin:0;accent-color:#4f46e5}
.cfbld-svc-text{display:flex;flex-direction:column;gap:1px;min-width:0}
.cfbld-svc-text b{font-size:12px;font-weight:700;color:#1a2035}
.cfbld-svc-text em{font-size:10.5px;color:#94a3b8;font-style:normal}
.cfbld-svc-title{flex:1.4;min-width:100px}
.cfbld-svc-cost{width:128px;flex-shrink:0}
.cfbld-svc.is-selected .cfbld-svc-head .cfbld-lbl{background:#eef2ff}
.cfbld-sc-tray{margin:0 6px 6px;border:1px solid #dbeafe;border-radius:8px;background:#fff;padding:9px 8px 7px}
.cfbld-sc-grid{display:grid;grid-template-columns:minmax(0,1fr) 108px 108px;gap:8px}
.cfbld-card .cfbld-sc-grid input,.cfbld-card .cfbld-sc-grid select{font-size:11.5px;padding-left:8px;padding-right:8px}
.cfbld-money{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;background:#f0fdfa;border:1px solid #99f6e4;border-radius:8px;padding:6px 10px;font-size:11.5px;color:#0f766e;margin-top:10px}
.cfbld-money b{font-size:13px}.cfbld-money .loss{color:#dc2626}
.cfbld-breakdown{display:grid;grid-template-columns:1fr 1fr;gap:14px;border:1px solid #e7ecf3;border-radius:9px;padding:10px;margin-top:10px;font-size:11px}
.cfbld-breakdown h5{font-size:10px;color:#94a3b8;text-transform:uppercase;margin-bottom:5px}
.cfbld-breakdown p{display:flex;justify-content:space-between;gap:8px;margin:3px 0;color:#334155;font-size:11px}
.cfbld-breakdown p.total{border-top:1px solid #e7ecf3;padding-top:5px;font-weight:700}.cfbld-breakdown p.profit{color:#0f766e}.cfbld-breakdown p.loss{color:#dc2626}
.cfbld-card-tags{display:none}.cfbld-card.is-collapsed .cfbld-card-tags{display:flex}
@media(max-width:1100px){.cfbld-columns{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.cfbld-sc-grid{grid-template-columns:minmax(0,1fr) 104px 104px}.cfbld-svc-cost{width:104px}.cfbld-svc-head{gap:6px}}
@media(max-width:900px){.cfbld-columns{grid-template-columns:1fr}.cfbld-services>h3 small{white-space:normal}}
