/* File identity is teal, distinct from Flight's orange / violet modals. */
.cfbld-header{background:linear-gradient(110deg,#0f766e,#075985)}
.cfbld-steps [role=tab].is-on{color:#0f766e;border-bottom-color:#0d9488}.cfbld-steps .is-on .cfbld-step-n{background:#0d9488}
.cfbld-box #cfbld-next{background:#f0fdfa;border-color:#99f6e4;color:#0f766e}.cfbld-card input:focus,.cfbld-card select:focus,.cfbld-card textarea:focus{border-color:#0d9488;box-shadow:0 0 0 3px #0d948817}
.cfbld-review-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;border-bottom:1px solid #edf1f7;padding:0 0 10px;margin-bottom:12px}
.cfbld-review-heading h3{margin:0;font-size:10.5px;letter-spacing:.7px;text-transform:uppercase;color:#64748b}.cfbld-review-heading span{font-size:9px;font-weight:600;letter-spacing:.7px;text-transform:uppercase;color:#64748b}
.cfbld-review-panels{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px}
