.cfbld-review-panel h4{display:flex;align-items:center;gap:8px;background:#f8fafc;padding:10px 13px;border-bottom:1px solid #eaf0f7;color:#64748b;letter-spacing:.5px;text-transform:uppercase;font-size:10px;font-weight:700;margin:0}
.cfbld-review-panel h4 span{background:#dff5f0;color:#0f766e;border-radius:12px;padding:1px 7px}
.cfbld-review-panel dl{display:grid;grid-template-columns:auto minmax(0,1fr);gap:8px 14px;padding:12px 13px;font-size:11px}.cfbld-review-panel dt{color:#94a3b8}.cfbld-review-panel dd{text-align:right;color:#25324d;font-weight:600;overflow-wrap:anywhere}
.cfbld-review-scroll{overflow:auto}.cfbld-review-table{width:100%;border-collapse:collapse;font-size:11px;min-width:1050px}
.cfbld-review-table th{font-size:9px;text-transform:uppercase;color:#8da0ba;text-align:left;padding:9px 10px;font-weight:700}.cfbld-review-table td{padding:10px;border-top:1px solid #e8eef6;vertical-align:top;color:#25324d}.cfbld-review-table td small{display:block;font-size:10px;line-height:1.7;color:#8da0ba;max-width:180px;overflow-wrap:anywhere}.cfbld-review-table td.amount{text-align:right;white-space:nowrap}.cfbld-review-table th:nth-last-child(n+2):nth-last-child(-n+4){text-align:right}.cfbld-review-table .profit{color:#0f766e}.cfbld-review-table .loss{color:#dc2626}.cfbld-review-table .pending{color:#b45309}.cfbld-review-table .cfbld-review-edit{width:25px;height:25px;padding:0;color:#0f766e;background:#f0fdfa;border-color:#bce8dc}
.cfbld-review-totals{display:flex;flex-wrap:wrap;gap:28px;background:#f0fdfa;border:1px solid #99f6e4;padding:12px 16px;border-radius:9px;margin-top:12px}.cfbld-review-totals small{display:block;font-size:9px;color:#5faaa3;text-transform:uppercase;font-weight:700;letter-spacing:.4px}.cfbld-review-totals b{display:block;font-size:17px;color:#0f766e;margin-top:5px}.cfbld-review-totals b.loss{color:#dc2626}
.cfbld-review-warnings{background:#fffbef;border:1px solid #fbd77a;border-radius:9px;padding:11px 13px;margin-bottom:12px;color:#92400e;font-size:11px}.cfbld-review-warnings b{display:block;margin-bottom:5px}.cfbld-review-warnings button{display:block;background:none;border:0;padding:3px 0;color:#b45309;text-decoration:underline;text-decoration-style:dotted;text-align:left}.cfbld-review-warnings button.blocker{color:#b91c1c}.cfbld-box .cfbld-review-footnote{font-size:10px;color:#8da0ba;line-height:1.6;margin-top:10px}
@media(max-width:700px){.cfbld-review-panels{grid-template-columns:1fr}.cfbld-review-heading{align-items:start;flex-direction:column;gap:5px}.cfbld-review-totals{gap:15px}}
